-- Efesto's page shows the current public site's content (issue #449): its
-- two images (files in public/project-photos/efesto/) as a gallery, and its
-- five key characteristics in place of the Why section. The import gave
-- Efesto no gallery, so the gallery is set whole. Every stored version of
-- Efesto (published and draft) gets both values. Written by
-- `revisionSql(efestoSiteContent)` (lib/project-content/revision.ts,
-- import.ts); lib/project-content/content.test.ts checks this file holds
-- exactly its output.
UPDATE "project_versions" SET "content" = jsonb_set(jsonb_set("content", '{gallery}', '{"title":"Designed in-house.","items":[{"src":"/project-photos/efesto/injector-head.webp","alt":"A cutaway of the Efesto injector head, where it joins the combustion chamber","caption":"Efesto injector head"},{"src":"/project-photos/efesto/rocketforge.webp","alt":"The RocketForge main screen, with fields for chamber pressure, oxidizer, fuel and mixture ratio","caption":"RocketForge, the Team''s engine design tool"}]}'::jsonb, true), '{reasons}', '{"eyebrow":"CHARACTERISTICS","title":"What sets Efesto apart.","items":[{"title":"Reusability","text":"Efesto is a regenerative liquid engine. It is meant as a small, reusable propulsion system for the first stage of a micro launcher."},{"title":"New materials","text":"Copper alloys keep the chamber walls cool, and high-strength steel or nickel alloys keep them stiff. With Politecnico''s R&D partnership, the chamber uses new copper-based metal matrix composites."},{"title":"New technologies","text":"The whole engine assembly is to be made by additive manufacturing. This opens new shapes and a lighter engine."},{"title":"Static fire qualification","text":"Efesto is designed to fire on a new test bench. Qualification tests there will check it meets the mission''s targets."},{"title":"Simplicity","text":"A regenerative pressure-fed cycle gives strong results with a simpler design than electric-pump-fed or open cycles."}]}'::jsonb, true) WHERE "content"->>'slug' = 'efesto';
